xpath.script:
(function(){
    try {
        var btn = document.currentScript.previousElementSibling;
        var templateId = btn && btn.dataset.productTemplateId;
        if (!templateId) return;
        var ids = JSON.parse(localStorage.getItem('av_wish_ids') || '[]');
        if (ids.includes(String(templateId))) {
            var icon = btn.querySelector('.fa');
            if (icon) { icon.className = icon.className.replace('fa-star-o', 'fa-star'); }
            btn.title = 'Added to wishlist';
        }
    } catch(e) {}
})();

div.script:
document.addEventListener('DOMContentLoaded', function() {
    var links = document.querySelectorAll('.av-privacy-nav-link');
    var sections = Array.from(links).map(function(l) {
        return document.querySelector(l.getAttribute('href'));
    }).filter(Boolean);
    function onScroll() {
        var scrollY = window.scrollY + 140;
        var active = sections[0];
        sections.forEach(function(s) { if (s.offsetTop <= scrollY) active = s; });
        links.forEach(function(l) {
            l.classList.toggle('active', l.getAttribute('href') === '#' + active.id);
        });
    }
    window.addEventListener('scroll', onScroll, {passive: true});

    // Accordion sidebar: open one policy at a time, show only its section
    var policyToggles = document.querySelectorAll('.av-privacy-sidebar-toggle');
    var policySections = document.querySelectorAll('.av-policy-section');
    var heroIcon  = document.getElementById('av-policy-hero-icon');
    var heroTitle = document.getElementById('av-policy-hero-title');
    var heroSub   = document.getElementById('av-policy-hero-sub');
    var policyHero = {
        privacy:  {icon: 'fa-shield',       title: 'Privacy Policy',  sub: 'This Privacy Policy explains how Aveenix collects, uses, stores, and protects your personal information when you use our services.'},
        'return': {icon: 'fa-undo',         title: 'Return Policy',   sub: 'How cancellations, returns, refunds, and exchanges work across different product types available on our platform.'},
        security: {icon: 'fa-lock',         title: 'Security Policy', sub: 'How we protect your data and secure every transaction with industry-standard encryption and trusted payment gateways.'},
        sellers:  {icon: 'fa-shopping-bag', title: 'Sellers Policy',  sub: 'A flexible platform to reach customers, manage products, and grow your online business with confidence.'},
        shipping: {icon: 'fa-truck',        title: 'Shipping Policy', sub: 'How shipping works, including delivery options, processing times, international shipping, customs, and order tracking.'},
        cashback: {icon: 'fa-gift',         title: 'Cashback Policy', sub: 'Earn rewards on every purchase. Learn how cashback is earned, tracked, and managed on the Aveenix platform.'},
        program:  {icon: 'fa-gift',         title: 'Aveenix Cashback Program', sub: 'Welcome to Aveenix. By participating in the Cashback Program, you agree to the terms outlined below. Please read them carefully.'}
    };
    function activatePolicy(key) {
        policyToggles.forEach(function(t) {
            var on = t.getAttribute('data-policy') === key;
            t.classList.toggle('is-open', on);
            t.setAttribute('aria-expanded', on ? 'true' : 'false');
            var nav = t.nextElementSibling;
            if (nav && nav.classList.contains('av-privacy-nav')) {
                nav.classList.toggle('is-collapsed', !on);
            }
        });
        policySections.forEach(function(s) {
            s.hidden = s.getAttribute('data-policy') !== key;
        });
        var h = policyHero[key];
        if (h && heroIcon && heroTitle && heroSub) {
            heroIcon.className = 'fa ' + h.icon;
            heroTitle.textContent = h.title;
            heroSub.textContent = h.sub;
        }
    }
    policyToggles.forEach(function(t) {
        t.addEventListener('click', function() {
            activatePolicy(t.getAttribute('data-policy'));
        });
    });

    // Expand/collapse privacy topic cards
    document.querySelectorAll('.av-privacy-topic-head').forEach(function(head) {
        head.addEventListener('click', function() {
            var card = head.closest('.av-privacy-topic-card');
            var open = card.classList.toggle('is-open');
            head.setAttribute('aria-expanded', open ? 'true' : 'false');
        });
    });

    // Nav link click → expand matching card + scroll to it
    document.querySelectorAll('.av-privacy-nav-link').forEach(function(link) {
        link.addEventListener('click', function() {
            var href = link.getAttribute('href');
            if (!href || href.charAt(0) !== '#') return;
            var target = document.getElementById(href.slice(1));
            if (!target) return;
            var card = target.querySelector('.av-privacy-topic-card');
            var head = target.querySelector('.av-privacy-topic-head');
            if (card && !card.classList.contains('is-open')) {
                card.classList.add('is-open');
                if (head) head.setAttribute('aria-expanded', 'true');
            }
        });
    });
});

document.addEventListener('DOMContentLoaded', function() {
    // Sidebar group toggle (+/-)
    document.querySelectorAll('.av-privacy-sidebar-toggle').forEach(function(t) {
        t.addEventListener('click', function() {
            var open = t.classList.toggle('is-open');
            t.setAttribute('aria-expanded', open ? 'true' : 'false');
            var nav = t.nextElementSibling;
            if (nav && nav.classList.contains('av-privacy-nav')) {
                nav.classList.toggle('is-collapsed', !open);
            }
        });
    });
    // Topic card expand/collapse
    document.querySelectorAll('.av-privacy-topic-head').forEach(function(head) {
        head.addEventListener('click', function() {
            var card = head.closest('.av-privacy-topic-card');
            var open = card.classList.toggle('is-open');
            head.setAttribute('aria-expanded', open ? 'true' : 'false');
        });
    });

    // Nav link click → expand matching card + scroll to it
    document.querySelectorAll('.av-privacy-nav-link').forEach(function(link) {
        link.addEventListener('click', function(e) {
            var href = link.getAttribute('href');
            if (!href || href.charAt(0) !== '#') return;
            var target = document.getElementById(href.slice(1));
            if (!target) return;
            var card = target.querySelector('.av-privacy-topic-card');
            var head = target.querySelector('.av-privacy-topic-head');
            if (card && !card.classList.contains('is-open')) {
                card.classList.add('is-open');
                if (head) head.setAttribute('aria-expanded', 'true');
            }
        });
    });
});

main.script:

document.addEventListener('DOMContentLoaded', function() {
    const slug = document.getElementById('dyn-breadcrumb-cat').getAttribute('data-slug');

    function renderArticle(article) {
        document.getElementById('dyn-breadcrumb-cat').innerText = (article.source && article.source.name) ? article.source.name : 'News';
        document.getElementById('dyn-category').innerText = (article.source && article.source.name) ? article.source.name : 'NEWS';
        document.getElementById('dyn-title').innerText = article.title;
        document.getElementById('dyn-author').innerText = article.author || 'Staff Reporter';

        document.getElementById('dyn-views').innerText = Math.floor(Math.random() * 50000) + 1000;

        const d = new Date(article.publishedAt);
        document.getElementById('dyn-date').innerText = isNaN(d) ? 'Just now' : d.toLocaleDateString('en-US', {month: 'long', day: 'numeric', year: 'numeric'});

        const img = document.getElementById('dyn-image');
        if(article.urlToImage) {
            img.src = article.urlToImage;
        } else {
            img.style.display = 'none';
        }

        document.getElementById('dyn-caption').innerText = article.title;

        let contentHTML = `<p class="lead mb-4" style="font-size:18px; line-height:1.8;"><strong>${article.description || ''}</strong></p>`;

        if (article.description) {
            let sentences = article.description.split('. ');
            let p1 = sentences.slice(0, Math.ceil(sentences.length/2)).join('. ');
            let p2 = sentences.slice(Math.ceil(sentences.length/2)).join('. ');
            if(p1.length > 0 && !p1.endsWith('.')) p1 += '.';
            if(p2.length > 0 && !p2.endsWith('.')) p2 += '.';

            if(p1) contentHTML += `<p style="font-size:16px; line-height:1.8; margin-bottom:20px; color:var(--text-color);">${p1}</p>`;
            if(p2) contentHTML += `<p style="font-size:16px; line-height:1.8; margin-bottom:20px; color:var(--text-color);">${p2}</p>`;
        }

        // Add a loading indicator for the full text
        contentHTML += `<div id="nm-full-text-loader" style="text-align:center; padding: 20px;"><i class="fa fa-spinner fa-spin fa-2x text-muted"></i><p class="text-muted mt-2">Extracting full article...</p></div>`;

        document.getElementById('dyn-content').innerHTML = contentHTML;

        // Fetch full article from our new backend scraper
        if (article.url) {
            fetch('/news/fetch_article_content?url=' + encodeURIComponent(article.url))
            .then(r => r.json())
            .then(data => {
                const loader = document.getElementById('nm-full-text-loader');
                if(loader) loader.remove();

                if(data && data.content && data.content.length > 0) {
                    let fullHTML = `<p class="lead mb-4" style="font-size:18px; line-height:1.8;"><strong>${article.description || ''}</strong></p>`;
                    data.content.forEach(p => {
                        fullHTML += `<p style="font-size:16px; line-height:1.8; margin-bottom:20px; color:var(--text-color);">${p}</p>`;
                    });
                    document.getElementById('dyn-content').innerHTML = fullHTML;
                }
            }).catch(e => {
                const loader = document.getElementById('nm-full-text-loader');
                if(loader) loader.remove();
            });
        }

        // Fetch sidebar articles
        fetch(`https://newsdata.io/api/1/latest?apikey=pub_f6edd3f794a346e3adada5b038854104&country=us&language=en&category=business,education,entertainment,lifestyle,world&prioritydomain=top&removeduplicate=1`)
            .then(res => res.json())
            .then(data => {
                if(data && data.status === 'success' && data.results) {
                    const mappedResults = data.results.map(r => ({
                        title: r.title,
                        url: r.link,
                        urlToImage: r.image_url,
                        publishedAt: r.pubDate,
                        author: (r.creator && r.creator.length > 0) ? r.creator[0] : 'Staff Reporter',
                        source: { name: r.source_name || 'News' },
                        description: r.description,
                        content: r.content
                    }));
                    const sideArts = mappedResults.filter(a => a.urlToImage && !a.urlToImage.includes('stimg.co') && a.title !== article.title).slice(0, 5);
                    let sideHTML = '';
                    sideArts.forEach(sa => {
                        let sideSlug = sa.title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)+/g, '');
                        if(!sideSlug) sideSlug = 'article';

                        sideHTML += `
                        <div class="d-flex align-items-center mb-3">
                            <img src="${sa.urlToImage}" class="rounded-circle me-3" style="width:60px; height:60px; object-fit:cover;"/>
                            <div>
                                <div style="font-size:10px; color:#008d7f;" class="text-uppercase fw-bold mb-1">${(sa.source && sa.source.name) ? sa.source.name : 'FACTS'}</div>
                                <a href="${sa.url}" style="font-size:13px; font-weight:600; color:var(--heading-color); line-height:1.2; display:block;" onclick="localStorage.setItem('nm_article_${sideSlug}', decodeURIComponent('${encodeURIComponent(JSON.stringify(sa))}')); window.location.href='/news/article/${sideSlug}'; return false;">${sa.title}</a>
                            </div>
                        </div>
                        `;
                    });
                    document.getElementById('dyn-latest-articles').innerHTML = sideHTML;
                }
            });
    }

    const articleData = localStorage.getItem('nm_article_' + slug);
    if(articleData) {
        renderArticle(JSON.parse(articleData));
    } else {
        // If direct link (no localStorage), fetch directly from API!
        fetch(`https://newsdata.io/api/1/latest?apikey=pub_f6edd3f794a346e3adada5b038854104&country=us&language=en&category=business,education,entertainment,lifestyle,world&prioritydomain=top&removeduplicate=1`)
        .then(r => r.json())
        .then(data => {
            if(data && data.status === 'success' && data.results) {
                const mappedResults = data.results.map(r => ({
                    title: r.title,
                    url: r.link,
                    urlToImage: r.image_url,
                    publishedAt: r.pubDate,
                    author: (r.creator && r.creator.length > 0) ? r.creator[0] : 'Staff Reporter',
                    source: { name: r.source_name || 'News' },
                    description: r.description,
                    content: r.content
                }));
                const article = mappedResults.find(a => {
                    let s = a.title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)+/g, '');
                    return s === slug;
                });
                if (article) {
                    renderArticle(article);
                } else {
                    document.getElementById('dyn-title').innerText = "Article not found";
                    document.getElementById('dyn-content').innerHTML = "<p>Please return to the news page and select an article.</p>";
                }
            }
        }).catch(() => {
            document.getElementById('dyn-title').innerText = "Article not found";
            document.getElementById('dyn-content').innerHTML = "<p>Could not fetch from API.</p>";
        });
    }
});
